# --- sets ---------------------------------------------------------------------------------------------------------

# a smoke of mm's CLI: the suites that run its commonest commands (bun src/cli.ts) on a throwaway MM_HOME, for a file
# every command loads (src/cli.ts, src/env.ts, src/project.ts...). The rest of the CLI suites run on the files they
# test (and all of them in the nightly full run, sy-sbjh step 3).
set cli-smoke test/names.sh test/vault.sh test/outside.sh test/template-base.sh test/update-lock.sh test/needs-fill.sh
set cli-smoke test/obs-home.sh test/api.sh

# the suites that take an mm built from the head ({mm}): a file only the build reads (tsconfig, a .d.ts)
set build test/needs-fill.sh test/npm-lock.sh

# the leads' and setup's settings as config-check renders and checks them (permissions, denies, the guard hook)
set settings test/denies.sh test/guard.sh test/brain-deny.sh test/sysworkers.sh test/writing-rule.sh

# a brief (CLAUDE.md, START.md, SKILL.md): the writing rule's section, and a board rendered as mm new lays it out
set brief test/writing-rule.sh test/template-base.sh

# a board built from template/site (vite) and opened in a browser: for a site file every page loads
set site-smoke test/board-space.mjs test/board-phone.mjs

# the board's site and its server (every suite that starts template/site's server)
set site test/board-*.mjs test/lead-state.mjs test/config-review.mjs test/project-item.mjs test/waiting-phone.mjs

# the containers built from box/ and the Docker wrapper
set containers test/mm-docker-container.sh test/box-egress.sh test/front-container.sh test/doop-container.sh
set containers test/doop-designs.sh test/doop-gateway.sh test/box.sh test/doop.sh

# the libs nearly every bin imports (svc.mjs, obs.mjs): one suite or two per bin family
set engine-smoke test/wake-start.mjs test/supervisor.mjs test/lead.sh test/message.mjs test/upstream.mjs test/sockets.sh
set engine-smoke test/engine-drift.sh test/raci.mjs test/flow.mjs test/sentinel-assist.mjs test/sysworkers.sh

